const input = $input.first().json;
const job = input.job ?? {};
if (job.job_id !== 'DEMO-001' || !job.title || !job.description) {
  throw new Error('Fictional job contract is invalid');
}
return [{ json: { ...input, validation: { valid: true } } }];

const input = $input.first().json;
const skills = input.job.skills ?? [];
const skillScore = Math.min(40, skills.length * 10);
const clarityScore = input.job.description.length >= 40 ? 25 : 10;
const budgetScore = input.job.budget >= 1000 ? 25 : 15;
const total = skillScore + clarityScore + budgetScore;
return [{ json: { ...input, opportunity_score: { skill_score: skillScore, clarity_score: clarityScore, budget_score: budgetScore, total } } }];

const input = $input.first().json;
const evidence = [
  { id: 'FICTION-001', source: 'fictional-case-study.md', claim: 'Designed validation gates for multi-stage workflows.', classification: 'TRANSFERABLE' },
  { id: 'FICTION-002', source: 'fictional-project-note.md', claim: 'Implemented deterministic scoring and structured handoffs.', classification: 'EXACT' }
];
return [{ json: { ...input, evidence } }];

const input = $input.first().json;
const approved = input.opportunity_score.total >= 70 && input.evidence.length >= 2;
return [{ json: { ...input, decision: { recommendation: approved ? 'PROCEED' : 'SKIP', reason: approved ? 'The fictional opportunity meets the deterministic demo threshold.' : 'The fictional opportunity does not meet the demo threshold.' } } }];

const input = $input.first().json;
const proposal = `Hello,

I can help with the fictional ${input.job.title} project. The demonstration evidence shows experience with validation gates and deterministic workflow design. I would begin by confirming the sample data contract, then implement and test each synchronization step.

Regards,
Demo Consultant`;
return [{ json: { ...input, proposal } }];

const input = $input.first().json;
const forbidden = ['guaranteed result', 'real customer', 'production deployment'];
const violations = forbidden.filter(term => input.proposal.toLowerCase().includes(term));
if (violations.length) {
  throw new Error(`Proposal audit failed: ${violations.join(', ')}`);
}
return [{ json: { ...input, audit: { passed: true, fictional_data_only: true, evidence_items_checked: input.evidence.length } } }];
